/**
 * Upper critical values of Hartley's Fmax = s²max / s²min for k groups of equal
 * size, each variance with ν = n − 1 degrees of freedom.
 *
 * Layout follows Pearson & Hartley, "Biometrika Tables for Statisticians",
 * Vol. I (3rd ed., 1966), Table 31 (α = 0.05 and 0.01; k = 2…12; ν = 2…10, 12,
 * 15, 20, 30, 60). The values were regenerated by numerically integrating the
 * exact distribution of Fmax, P(Fmax ≤ c) = k ∫ f(x)[F(cx) − F(x)]^{k−1} x dx
 * with f, F the χ²_ν density and CDF, and rounded to the table's printed
 * precision. Checked against the printed ν = 2 rows and the k = 2 column
 * (which equals F(1 − α/2; ν, ν)): all agree except α = 0.01, k = 3, ν = 2,
 * where the exact value is 447.50 and the printed table shows 448.
 */
export const HARTLEY_DFS = [2, 3, 4, 5, 6, 7, 8, 9, 10, 12, 15, 20, 30, 60] as const;

